insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('MA', 'MA-P-10', 'Achats de biens et services 10 % (déductible)', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 101 pour le droit à déduction ; art. 99-B-1° pour le taux réduit de 10 % avec droit à déduction.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null),
  ('MA', 'MA-P-20', 'Achats de biens et services 20 % (déductible)', '{}'::jsonb, null, 'percent', 20, 'purchase', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 101 — la taxe dont les redevables peuvent opérer la déduction est celle qui a grevé les éléments du prix d''une opération imposable, figurant sur des factures répondant aux conditions de l''article 146 ; art. 99-A pour le taux.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null),
  ('MA', 'MA-P-20-IMMO', 'Achats d''immobilisations 20 % (déductible)', '{}'::jsonb, null, 'percent', 20, 'purchase', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 101 — déduction de la taxe ayant grevé les biens constituant des immobilisations ; art. 104 — la déduction est calculée dès le mois de l''acquisition, sous réserve des régularisations qu''entraîne une cession ou un changement d''affectation ; art. 99-A pour le taux.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null),
  ('MA', 'MA-P-20-ND', 'Achat de véhicule de tourisme 20 % (non déductible, art. 106)', '{}'::jsonb, null, 'percent', 20, 'purchase', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 106-II — n''ouvre pas droit à déduction la taxe ayant grevé les véhicules de transport de personnes, à l''exclusion de ceux utilisés pour le transport public, le transport collectif du personnel des entreprises ou constituant l''outil principal d''exploitation d''une entreprise de location de voitures. La taxe non déductible fait partie du coût du véhicule.', 'S', null, 140, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null),
  ('MA', 'MA-P-NR-20', 'Prestation d''un prestataire étranger non établi, sans représentant fiscal (art. 115)', '{}'::jsonb, null, 'percent', 20, 'purchase', 'foreign_services_received', date '2026-01-01', null, 'Code général des impôts, art. 115 — toute personne n''ayant pas au Maroc d''établissement stable et y effectuant des opérations imposables est tenue de faire accréditer auprès de l''administration fiscale un représentant domicilié au Maroc ; à défaut, la taxe due, ainsi que la pénalité et les majorations y afférentes, sont dues par la partie versante pour le compte de la personne non-résidente. Lorsque le client marocain est lui-même redevable de la taxe, il déclare le montant hors taxe de l''opération, calcule la taxe exigible et procède simultanément à sa déduction (autoliquidation) ; art. 96 pour l''assujettissement des prestations de services utilisées ou exploitées au Maroc.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null),
  ('MA', 'MA-S-10-ADD', 'Ventes taux réduit 10 % (avec droit à déduction)', '{}'::jsonb, 'Opérations de restauration et autres opérations visées à l''article 99-B taxées à 10 % avec droit à déduction', 'percent', 10, 'sale', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 99-B-1° — taux réduit de 10 % avec droit à déduction, notamment pour les opérations de restauration. La loi de finances pour 2026 (loi n° 50-25) achève la convergence de plusieurs opérations auparavant taxées à 14 % ou à 7 % (transport, eau, sucre raffiné) vers ce taux de 10 % ; seules les catégories que le pack a pu vérifier par recoupement de plusieurs commentaires professionnels concordants sont reprises ici, faute d''avoir pu extraire le texte intégral de l''article 99 — voir la section « From Morocco » de docs/international.md.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null),
  ('MA', 'MA-S-20', 'Ventes taux normal 20 %', '{}'::jsonb, 'Ventes et prestations de services imposables au taux normal', 'percent', 20, 'sale', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 99-A — taux normal de 20 %, taux applicable à toutes les opérations imposables que la loi ne soumet pas expressément à un autre taux. Ancien taux réduit de 14 %, encore en vigueur en 2023 sur certaines opérations, entièrement convergé vers 20 % ou 10 % par le calendrier de convergence de la loi de finances pour 2024 (loi n° 55-23), poursuivi par la loi de finances pour 2025 (loi n° 60-24) et achevé par la loi de finances pour 2026 (loi n° 50-25) : à la date de ce pack, l''article 99 ne connaît plus que le taux normal de 20 % (A) et le taux réduit de 10 % (B).', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null),
  ('MA', 'MA-S-EXO', 'Opération exonérée sans droit à déduction (art. 91)', '{}'::jsonb, 'Vente de pain, exonérée sans droit à déduction', 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'Code général des impôts, art. 91-I — sont exonérées de la taxe sur la valeur ajoutée sans droit à déduction les ventes autrement qu''à consommer sur place portant sur le pain, ainsi que la farine et les céréales servant à sa fabrication.', 'E', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null),
  ('MA', 'MA-S-EXP', 'Exportation exonérée (avec droit à déduction)', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2026-01-01', null, 'Code général des impôts, art. 92-I-1° — sont exonérées de la taxe sur la valeur ajoutée avec bénéfice du droit à déduction les produits livrés et les prestations de services rendues à l''exportation par les assujettis ; l''exonération s''applique à la dernière vente effectuée et à la dernière prestation de service rendue sur le territoire marocain ayant pour effet direct et immédiat de réaliser l''exportation, sur justification par l''exportateur des titres de transport, des documents douaniers ou de tout document en tenant lieu.', 'G', null, 30, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi2026', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

