    ('MA-P-NR-20', 'invoice', 'base', 100, null, 'CANR', array['CANR']::text[], 100, 'MA-TVA', 10),
    ('MA-P-NR-20', 'invoice', 'tax', 100, '34552', 'DEDNR', array['DEDNR']::text[], 100, 'MA-TVA', 20),
    ('MA-P-NR-20', 'invoice', 'tax', -100, '4455', 'TVANR', array['TVANR']::text[], 100, 'MA-TVA', 30),
    ('MA-P-NR-20', 'credit_note', 'base', 100, null, 'CANR', array['CANR']::text[], -100, 'MA-TVA', 10),
    ('MA-P-NR-20', 'credit_note', 'tax', 100, '34552', 'DEDNR', array['DEDNR']::text[], -100, 'MA-TVA', 20),
    ('MA-P-NR-20', 'credit_note', 'tax', -100, '4455', 'TVANR', array['TVANR']::text[], -100, 'MA-TVA', 30),
    ('MA-S-10-ADD', 'invoice', 'base', 100, null, 'CA10', array['CA10']::text[], 100, 'MA-TVA', 10),
