insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MA', 'MA-TVA', 'Déclaration du chiffre d''affaires — taxe sur la valeur ajoutée', array['month', 'quarter']::declaration_period[], null, date '2026-01-01', null, 'Code général des impôts, art. 108 — la déclaration est mensuelle pour les redevables dont le chiffre d''affaires taxable réalisé au cours de l''année écoulée atteint ou dépasse 1 000 000 de dirhams, ainsi que pour toute personne n''ayant pas d''établissement au Maroc et y effectuant des opérations imposables ; elle est trimestrielle pour les autres redevables, sur option possible pour le régime mensuel avant le 31 janvier. La cadence dépend donc du chiffre d''affaires de l''entreprise : le pack n''en propose aucune par défaut. La déclaration est servie en ligne sur le télé-service SIMPL-TVA (tax.gov.ma), en six rubriques A à F : CA total, CA imposable, opérations réalisées avec des contribuables non-résidents (art. 115), calcul de la taxe exigible, déductions, paiement de la taxe. L''imprimé n''étant pas publié sous une forme numérotée consultée pour ce pack, les codes de case ci-dessous sont ceux de ces six rubriques et non ceux, s''ils existent, d''un bordereau-avis papier.', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Code général des impôts, art. 108 et 110 — la déclaration du chiffre d''affaires, mensuelle ou trimestrielle, est déposée et la taxe correspondante versée avant l''expiration du mois qui suit la période. Le numéro exact de l''article fixant ce délai n''a pas pu être vérifié sur le texte intégral du Code à la date de ce pack — voir la section « From Morocco » de docs/international.md — et mérite une relecture par un professionnel local avant mise en production.', 'cgi2026', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

