insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('MA-CGNC-BL', 'MA', 'default', 'Bilan (BL) — modèle normal, masses et postes', 'balance_sheet', 'CGNC', date '1994-01-01', null, 'Code général de normalisation comptable, deuxième partie, Titre I — modèle du bilan du modèle normal. Les postes du bilan retenus ici regroupent, pour un pack de statut community, les comptes divisionnaires d''un même poste du cadre comptable en une seule ligne — le modèle normal officiel détaille davantage le passif circulant (fournisseurs, personnel, organismes sociaux, État, associés, autres créanciers et régularisation en postes distincts) ; voir la section « From Morocco » de docs/international.md.', 'cgnc'),
  ('MA-CGNC-CPC', 'MA', 'default', 'Compte de produits et charges (CPC) — modèle normal, en liste', 'income_statement', 'CGNC', date '1994-01-01', null, 'Code général de normalisation comptable, deuxième partie, Titre I — modèle du compte de produits et charges du modèle normal, présenté en liste avec dégagement du résultat d''exploitation, du résultat financier, du résultat courant, du résultat non courant et du résultat net de l''exercice.', 'cgnc')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

