update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Code général des impôts, art. 145-III — tout achat de biens ou de services effectué par un contribuable auprès d''un fournisseur soumis à la taxe professionnelle doit être appuyé d''une facture régulière comportant, entre autres mentions, un numéro pris dans une série continue et ininterrompue. Le paragraphe n''impose ni forme ni remise à zéro annuelle, que le format proposé ici (`{CODE}/{YYYY}/{NNNN}`) permet sans l''exiger. Le libellé exact du paragraphe III n''a pas pu être extrait du PDF officiel pour ce pack et a été recoupé sur plusieurs commentaires professionnels concordants — voir la section « From Morocco » de docs/international.md.',
  numbering_source_key          = 'cgi2026',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Code général des impôts, art. 95 — le fait générateur de la taxe est constitué par l''encaissement total ou partiel du prix des marchandises, des travaux ou des services (régime de l''encaissement, applicable de plein droit) ; les redevables qui en font la déclaration avant le 1er janvier, ou dans les trente jours de leur début d''activité, sont autorisés à acquitter la taxe d''après le régime des débits, la facturation valant alors fait générateur. invoice_if_issued dit le régime des débits sur option, qui devance l''encaissement de droit commun dès qu''il est retenu ; le pack ne code pas l''option elle-même, qui est un choix de l''entreprise et non une règle du texte.',
  tax_point_source_key          = 'cgi2026',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Le principe d''une obligation de facturation électronique existe dans la loi, à l''art. 145-IX du Code général des impôts (introduit par la loi de finances pour 2018 et dont l''entrée en application a été accélérée par la loi de finances pour 2024) : le contribuable doit se doter d''un système informatique de facturation répondant à des critères techniques fixés par l''administration, selon des modalités renvoyées à un décret d''application. Aucun décret d''application n''était publié au Bulletin officiel à la date de ce pack — la presse professionnelle rapportait, en avril 2026, un avant-projet transmis au secrétariat général du gouvernement et un déploiement par vagues annoncé par la Direction générale des Impôts en commençant par les grandes entreprises en B2B, sans date ni seuil de chiffre d''affaires officialisés, ni format technique arrêté par un texte publié. Le pack laisse donc `obligation` à `none` et le reste du bloc vide plutôt que d''anticiper un décret non publié : voir la section « From Morocco » de docs/international.md.',
  einvoice_source_key           = null,
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'MA';
